import type {BlogPost} from './data';

export const november18BlogBatch:readonly BlogPost[]=[{"slug":"callcenteroutsourced-build-a-first-call-resolution-measure-that-agents-trust","heroImage":"/daily18/callcenteroutsourced/callcenteroutsourced-build-a-first-call-resolution-measure-that-agents-trust.webp","title":"Build a first-call resolution measure that agents trust","excerpt":"A resolution measure that names the evidence, links repeat contacts, and shows agents the record before the score is final.","minutes":8,"intro":"Most contact centers claim to measure first-call resolution, then argue about the number every month. The disagreement usually starts with the definition, not the performance. A measure agents trust names the request, the action, the evidence, and the window before the first call is scored. The routine below builds that measure from the case record instead of from a dashboard total.","published":"2026-11-18","updated":"2026-11-18","stats":[{"value":"2.67 million","label":"U.S. customer service representative jobs in 2025","note":"BLS reports about 2.7 million customer service representative jobs; the figure frames the scale of the queue workload.","source":1},{"value":"$21.53","label":"median hourly wage in May 2025","note":"BLS median pay for customer service representatives in May 2025; wages vary by industry and geography.","source":1},{"value":"289,500","label":"projected annual openings, 2025 to 2035","note":"BLS projects annual openings from replacement needs, not from queue growth.","source":1}],"sections":[{"title":"Define resolution before you count it","paragraphs":["Write a definition of resolution that a reviewer can check against the case record. It should name the customer's request, the action taken, and the evidence that the issue closed. A definition that only says the call ended politely will count transfers and hang-ups as wins. Test the wording on ten closed cases before the team uses it in a score.","Include the cases where the agent gave a correct answer but the customer needed a second contact. Those cases are not automatic failures, and they are not clean resolutions either. Give the reviewer a third option for a resolved request with a follow-up task. The measure should show the follow-up without hiding the original work. Keep the list of actions short enough to read at a glance."]},{"title":"Choose the evidence for each contact","paragraphs":["Pick the record that proves the action, such as a payment posted, an address updated, or a ticket closed with the customer's confirmation. A note that says resolved is not evidence unless it names the action and the result. If the system cannot show the action, the case belongs in a separate review sample. Write the evidence rule in the same guide agents already use.","Keep the evidence field short so agents actually complete it. A long free-text box invites a summary that is hard to compare across the team. Use a fixed list of actions and one optional note for context. Review the list each quarter against the reasons customers actually call, and remove any option nobody selects. A field that nobody uses is a sign the list is too long or the screen sits too far from the note."]},{"title":"Separate repeat contacts from new ones","paragraphs":["A repeat contact is a new call about the same request inside a defined window. Count it against the original case, not against the agent who happened to answer the second call. Link the contacts with a shared case number or a verified match on the customer and request. Without that link, a repeat looks like fresh demand and the queue learns nothing.","Set the window by request type because a billing correction and a password reset do not behave the same way. Record the window in the measure so a later review can compare like with like. Show repeat contacts as a share of resolved cases, not as a raw count that grows with volume. A raw count makes a busy month look worse than a quiet one."]},{"title":"Set the measurement window by request type","paragraphs":["Some requests resolve on the call, while others depend on a back-office step that takes days. A single same-day window will mark every multi-step request as unresolved. Write a target window for each request type and start the clock at the customer's first contact. Review the window with the client before it becomes a performance target. If the client cannot agree on a window, publish the assumption beside the result.","Measure the cases that close inside the window and the ones that close later. A late close still tells the team something useful about the handoff. Report the late cases with the reason, such as a missing document or an approval queue. Do not fold them into the failure count without that context, because the fix may sit outside the call center."]},{"title":"Train agents on the close-out rule","paragraphs":["Give new agents the definition, the evidence list, and three example cases before they take live calls. Ask them to close out the examples and compare their answers with a supervisor. A short exercise exposes the difference between a polite ending and a verified resolution. Repeat the exercise when the definition changes so tenured agents do not drift back to habit.","Coach the close-out as part of the call, not as a separate task at the end of the shift. An agent who waits until the last hour will reconstruct the case from memory. Put the evidence field on the same screen as the case note so it is hard to skip. Check a sample of close-outs each week and share one good example with the team."]},{"title":"Review a sample with the agent","paragraphs":["Pull a sample that includes high scores, low scores, and cases with no evidence. Read the record with the agent and ask what happened after the call ended. The agent often knows about a callback or a system error that the record does not show. Add the missing detail to the case before the score is final. Ask the agent to open the record during the review so the gap is visible to both of you.","Do not turn the review into a dispute about a single percentage. The purpose is to test whether the definition and the evidence field work in practice. If several agents describe the same gap, fix the form or the system instead of coaching each person. Record the fix and the date so the next review starts from it. That record also protects the agent if a later reviewer questions the score."]},{"title":"Report resolution beside the queue result","paragraphs":["Show the resolution rate with the wait time, the abandon rate, and the repeat-contact share. A high resolution rate on a queue that abandons many callers does not describe a healthy service. Put the measures on one page so the client can see the tradeoff. State the sample size and the period under the table. Use the same period for every measure so a busy week is not compared with a quiet one.","Break the result down by request type and by team, not only by site. A site average can hide one request type that fails every week. Use the breakdown to choose a fix and a review date. The report should end with the next action, not only a number that invites a comparison the data cannot support. A short note that names the fix is enough, because a long narrative usually hides the missing action."]},{"title":"Audit the measure after a system change","paragraphs":["A new CRM, a changed ticket status, or a revised script can move the resolution rate without changing the service. Compare the same cases before and after the change, and check that the evidence field still captures the action. A drop that appears only in the report is a measurement problem until proven otherwise. Keep a copy of the old report beside the new one for the first month.","Ask the vendor which fields changed and whether old records were migrated. Test ten cases that span the change and read the audit trail. Update the definition and the training on the same day. Keep the old definition with the report so a later reader can explain the shift instead of guessing at the cause. That note is the difference between a trend the client can trust and a number that seems arbitrary."]}],"controlTable":[{"data":"Resolution definition","agent":"Applies the written rule to each case","manager":"Owns the definition and the exceptions"},{"data":"Evidence field","agent":"Names the action and the result","manager":"Reviews cases with no evidence"},{"data":"Repeat contact","agent":"Links the new call to the original case","manager":"Sets the window by request type"},{"data":"Late close","agent":"Records the reason for the delay","manager":"Routes the fix outside the queue"}],"scripts":[{"situation":"Closing a resolved case","text":"I have updated the address on your account and the confirmation number is on the case. I am noting that the change is complete so the next person can see it without asking you again."},{"situation":"Explaining a repeat contact","text":"I can see you called about this same request on Monday, so I am treating this as a continuation rather than a new issue. I will keep the original case open until the payment posts and the confirmation reaches you."}],"faqs":[{"question":"Should a transfer count as a failed resolution?","answer":"Not automatically. Count it as unresolved for the original owner and record the reason, because a transfer that reaches the right specialist may still serve the customer well."},{"question":"How long should the repeat-contact window be?","answer":"Long enough to catch the normal second contact for that request type and short enough to avoid linking unrelated calls. Set it per request type and write it down."}],"sources":[{"name":"Occupational Outlook Handbook: Customer Service Representatives","organization":"Bureau of Labor Statistics","date":"2026","url":"https://www.bls.gov/ooh/office-and-administrative-support/customer-service-representatives.htm","note":"Employment, wage, training, and outlook figures for customer service representatives."},{"name":"ISO 18295-1:2017 Customer contact centres","organization":"International Organization for Standardization","date":"2017","url":"https://www.iso.org/standard/64739.html","note":"Requirements for customer contact centre processes, people, and performance."},{"name":"GAO-20-283G: Assessing Data Reliability","organization":"U.S. Government Accountability Office","date":"2020","url":"https://www.gao.gov/products/gao-20-283g","note":"A practical framework for documenting data sources, testing reliability, and stating limitations."},{"name":"Fact Sheet #64: Call Centers under the Fair Labor Standards Act","organization":"U.S. Department of Labor, Wage and Hour Division","date":"2008","url":"https://www.dol.gov/agencies/whd/fact-sheets/64-flsa-call-centers","note":"Hours-worked, rest-period, and recordkeeping rules for call center employees."}],"related":[{"label":"Set a wrap-time limit that agents can meet","href":"/blog/callcenteroutsourced-set-a-wrap-time-limit-that-agents-can-meet"},{"label":"Review reporting and QA","href":"/services/reporting-and-qa"}]},{"slug":"callcenteroutsourced-run-a-new-hire-nesting-period-without-hiding-the-queue","heroImage":"/daily18/callcenteroutsourced/callcenteroutsourced-run-a-new-hire-nesting-period-without-hiding-the-queue.webp","title":"Run a new-hire nesting period without hiding the queue","excerpt":"A nesting plan that gives new agents graded live practice while the queue keeps its service level and the coach keeps their own schedule.","minutes":8,"intro":"Nesting is the bridge between classroom training and a solo queue, and it is easy to run badly in both directions. Leave new agents on the floor too early and the customer pays for the mistake. Keep them in supervised practice too long and the queue pays for the extra headcount. A workable plan states what nesting must prove and who covers the work while it happens.","published":"2026-11-18","updated":"2026-11-18","stats":[{"value":"2.67 million","label":"U.S. customer service representative jobs in 2025","note":"BLS reports about 2.7 million customer service representative jobs; the figure frames the scale of the queue workload.","source":1},{"value":"$21.53","label":"median hourly wage in May 2025","note":"BLS median pay for customer service representatives in May 2025; wages vary by industry and geography.","source":1},{"value":"289,500","label":"projected annual openings, 2025 to 2035","note":"BLS projects annual openings from replacement needs, not from queue growth.","source":1}],"sections":[{"title":"Decide what nesting is for","paragraphs":["Write the specific skills a new agent must show before solo work, such as a clean verification, a correct disposition, and a complete close-out. A nesting plan without those checkpoints becomes a long observation period with no exit. Name the person who signs the sign-off and the evidence they will read. Review the list with the client so the standard matches the account.","Separate the skills that need live calls from the ones a simulation can test. A system navigation drill can happen in a sandbox, while a frustrated customer needs a real conversation. Put the live skills at the end of nesting and the drills at the start. This order keeps the newest agents off the hardest calls until they have the basics."]},{"title":"Set the supervision ratio","paragraphs":["Decide how many new agents one coach can supervise at once, and write the ratio into the schedule. A coach who watches six screens at the same time is not coaching, only monitoring. Include the coach's own breaks and meetings in the ratio so the coverage is real. If the account cannot support the ratio, extend the classroom phase instead of pretending.","Count the coach's time as production capacity only when the coach is actually available for calls. Borrowing a coach to cover a queue gap removes the support the new agents need. Record the coaching hours in the plan and compare them with the actual week. A ratio that looks affordable on paper may still fail on a Monday morning. A ratio that ignores the coach's own workload is a plan for burnout, not training."]},{"title":"Keep a live-queue boundary","paragraphs":["Give new agents a defined share of live calls rather than an open queue login. Start with one call per hour and add contacts as the coach confirms the skills. The boundary protects the customer from a first-week mistake and protects the new agent from a volume spike. Publish the boundary so the scheduling team can plan capacity. The scheduling team should see the same boundary the coach uses on the floor.","Route the practice calls through the same skill group as the live queue so the reports stay comparable. Do not create a separate training queue that hides the new agent's handle time and transfers. When the agent moves to a full share, record the date and the coach who approved it. The queue report should show the ramp, not a sudden unexplained jump."]},{"title":"Build a graded call list","paragraphs":["Choose practice calls by the skill they test, not by whichever calls happen to arrive. A simple billing question tests verification, while a cancellation tests empathy and authority. Ask the coach to note which skill each call exercised and what the agent did well. Use the list to plan the next session instead of repeating the same easy call. A call that tests nothing on the checklist is practice, not assessment.","Include at least one call where the agent must say no or escalate. New agents often avoid those moments because they fear the score, and the avoidance becomes a habit. Let the coach take the call back when the risk is too high, then debrief the decision. A graded list prepares the agent for the moment the coach is not there."]},{"title":"Track the first solo week","paragraphs":["Treat the first solo week as part of nesting even though the agent is on a full schedule. Check the dispositions, the repeat contacts, and the transfers for each new agent. A mistake that appears on day two is cheaper to fix than one found at the monthly review. Assign a named buddy for questions that do not need a supervisor.","Ask the new agent what they could not find in the knowledge base during the week. Their fresh view often exposes a missing article or a confusing label. Fix one item per week and tell the agent it changed. That loop teaches the agent how to improve the queue instead of only how to survive it. Those small fixes are often the most useful output of a nesting cycle."]},{"title":"Protect the coach's own queue time","paragraphs":["A coach who is scheduled for calls cannot also watch a new agent's screen. Give the coaching block its own line in the schedule and treat it like a client meeting. If the queue needs the coach, name a backup coach rather than canceling the session. Record the canceled sessions so the pattern is visible to the account manager. A canceled coaching block is a data point, not a private favor.","Review the coach's schedule after the first nesting cycle. If coaching blocks are consistently overrun, the ratio or the staffing model is wrong. Fix the schedule before adding another class. A coach who is stretched across too many new agents will produce sign-offs that mean very little. The client is paying for a bench that can take calls, not for a sign-off sheet."]},{"title":"Report nesting results to the client","paragraphs":["Give the client the number of new agents, the skills signed off, the live-call share, and the first-week results. Show the coaching hours beside the production hours so the investment is visible. State what the new agents could not yet handle and when the next check happens. A client who sees the ramp can plan demand around it. That visibility also makes the coaching cost easier to defend at renewal.","Do not report a class average that hides one agent who is far behind. Name the support plan for that agent and the date of the next review. If the agent needs a different role, say so early rather than waiting for the probation deadline. The client should see an honest picture of the bench, not a polished completion rate."]},{"title":"End nesting with a written sign-off","paragraphs":["Close nesting with a short record that lists the skills, the sample calls, the coach, and the date. The new agent should read it and confirm that the examples match their experience. A sign-off without the evidence is only an administrative step. Keep it with the training file so a later audit can follow the path from class to queue.","Set a thirty-day check after the sign-off even though nesting is over. The check reviews quality, repeat contacts, and adherence for the new agent. If a skill has slipped, reopen coaching rather than waiting for the annual review. The sign-off marks a transition, not the end of support. Keep the same support number open for the first month after the sign-off."]}],"controlTable":[{"data":"Skill checklist","agent":"Practices each skill with the coach","manager":"Signs off only with evidence"},{"data":"Live-call share","agent":"Takes the agreed number of calls","manager":"Raises the share after review"},{"data":"Coaching block","agent":"Brings questions and cases","manager":"Protects the block in the schedule"},{"data":"First solo week","agent":"Uses the named buddy","manager":"Reviews dispositions and repeats"}],"scripts":[{"situation":"Handing a call to the coach","text":"I am going to bring my coach onto the line so we can finish this correctly. They will hear what you have already told me, so you will not need to repeat the details."},{"situation":"Explaining the nesting plan to a new agent","text":"For your first week you will take one live call each hour with me listening, and we will review it before the next one. The share rises when the checklist is complete, not when the calendar says so."}],"faqs":[{"question":"How long should nesting last?","answer":"Long enough to observe each required skill on a live call and short enough to keep the class engaged. Use the checklist rather than a fixed number of weeks."},{"question":"Should new agents be counted in the staffing plan?","answer":"Only for the share of live calls they actually take. Counting a full headcount before the ramp is complete overstates capacity and hides the coaching load."}],"sources":[{"name":"Occupational Outlook Handbook: Customer Service Representatives","organization":"Bureau of Labor Statistics","date":"2026","url":"https://www.bls.gov/ooh/office-and-administrative-support/customer-service-representatives.htm","note":"Employment, wage, training, and outlook figures for customer service representatives."},{"name":"Fact Sheet #64: Call Centers under the Fair Labor Standards Act","organization":"U.S. Department of Labor, Wage and Hour Division","date":"2008","url":"https://www.dol.gov/agencies/whd/fact-sheets/64-flsa-call-centers","note":"Hours-worked, rest-period, and recordkeeping rules for call center employees."},{"name":"Fair Labor Standards Act","organization":"U.S. Department of Labor, Wage and Hour Division","date":"2026","url":"https://www.dol.gov/agencies/whd/flsa","note":"Federal minimum wage, overtime, hours-worked, and recordkeeping obligations."},{"name":"ISO 18295-1:2017 Customer contact centres","organization":"International Organization for Standardization","date":"2017","url":"https://www.iso.org/standard/64739.html","note":"Requirements for customer contact centre processes, people, and performance."}],"related":[{"label":"Build a first-call resolution measure that agents trust","href":"/blog/callcenteroutsourced-build-a-first-call-resolution-measure-that-agents-trust"},{"label":"Review operations support","href":"/services/operations-support"}]},{"slug":"callcenteroutsourced-write-a-client-escalation-path-that-names-the-next-owner","heroImage":"/daily18/callcenteroutsourced/callcenteroutsourced-write-a-client-escalation-path-that-names-the-next-owner.webp","title":"Write a client escalation path that names the next owner","excerpt":"An escalation path with clear triggers, tiers, clocks, and a named owner at every step so a client issue never waits in an inbox.","minutes":8,"intro":"An escalation that reaches the right person on the second day is still a late escalation. Most paths fail because they name a department instead of a person, and because nobody writes down what triggers the move. A usable path fits on one page: trigger, tier, clock, owner, and the note that travels with the case. The steps below make that page real in daily work.","published":"2026-11-18","updated":"2026-11-18","stats":[{"value":"2.67 million","label":"U.S. customer service representative jobs in 2025","note":"BLS reports about 2.7 million customer service representative jobs; the figure frames the scale of the queue workload.","source":1},{"value":"$21.53","label":"median hourly wage in May 2025","note":"BLS median pay for customer service representatives in May 2025; wages vary by industry and geography.","source":1},{"value":"289,500","label":"projected annual openings, 2025 to 2035","note":"BLS projects annual openings from replacement needs, not from queue growth.","source":1}],"sections":[{"title":"Name the triggers","paragraphs":["Write the events that start an escalation, such as a missed service level for two intervals, a repeat complaint from the same customer, or a data issue the queue cannot correct. A trigger should be observable in a report or a case, not a feeling about the client's tone. Give each trigger a threshold and a time window so two supervisors reach the same decision. Write both in the same document so the team sees the difference.","Separate a customer escalation from a client escalation. A customer asks for a manager because the issue is unresolved, while a client contact raises a concern about the service itself. The two paths can share a record but need different owners and clocks. Mixing them sends a customer complaint to an account review that cannot answer the caller. The customer should always know which path they are on."]},{"title":"Set the clock for each tier","paragraphs":["Give each tier a response time and a resolution time, and start both when the trigger is recorded. A first-tier owner might acknowledge within one hour and resolve within one business day. The second tier gets a shorter clock for the acknowledgement because the case is already late. Write the clock in business hours and name the holiday calendar. A clock without a calendar is a promise that fails on the first holiday.","Stop the clock only when the customer or client has the answer, not when the internal handoff happens. A transfer between teams is progress, not resolution. Record each pause with a reason and the person who approved it. A paused clock that nobody reviews becomes a hidden backlog. Review the pauses weekly so a small delay does not become a standing excuse."]},{"title":"Write the handoff note","paragraphs":["The handoff note should state the issue, the customer's words, the action already taken, the promise made, and the next step. Keep it short enough to read on a phone but specific enough that the next owner does not call the customer to ask the same questions. Attach the recording or the case link rather than a paraphrase. The note should never require the next owner to open three systems to understand the issue.","Name the next owner in the note, not only the team. If the named person is unavailable, the note should list a backup before the case moves. A queue that accepts the case without an owner is a place where escalations go to wait. The receiving owner confirms acceptance in the record. An accepted case is the only proof that the handoff actually happened."]},{"title":"Keep the customer informed","paragraphs":["Tell the customer what will happen next and when they will hear an update, even when the answer is not ready. A short message with a named person and a time is better than silence followed by a late apology. Use the channel the customer chose, and record the message in the case. Write the next update before the current one expires.","Do not promise a resolution time the team cannot meet just to end the call. If the estimate changes, send a revised time before the old one passes. The customer should never have to call back to discover that the case stalled. A missed update is itself an escalation trigger. The customer's reply should also be recorded, even when it is only an acknowledgement."]},{"title":"Test the path with a drill","paragraphs":["Run one realistic case through every tier before the client needs it. Use a scenario such as a billing error that survives two contacts and requires a data fix. Time each handoff and note where the case waited. The drill will expose a missing backup or a clock that nobody owns. Give the drill a fixed time limit so the review measures the path, not the scenario.","Ask the people who took part what they had to guess. A path that depends on knowing who sits at a particular desk will fail on a holiday. Write the answer into the path and remove the guess. Repeat the drill after any change to the account team or the tools. A path that only works when the usual people are present is not ready for a holiday."]},{"title":"Review missed escalations","paragraphs":["Pull the cases that breached a clock and read the timeline, not only the final note. Look for the first point where the case had no owner or where a handoff waited for a meeting. Group the misses by cause so one fix can cover several cases. Do not treat every miss as an individual performance problem. Look for the case that sat in a shared inbox with no owner for a full day.","Share one anonymized miss with the team each month and ask what would have changed the outcome. The discussion should produce a specific edit to the path or the tooling. A review that ends with a reminder to be more careful has not fixed anything. Record the edit and check it at the next review. The team should leave the review with one edit, not a general reminder."]},{"title":"Publish the path to the client","paragraphs":["Give the client the same one-page path the team uses, including the triggers, the clocks, and the names or roles. A client who knows the path can raise an issue at the right tier instead of calling a personal contact. Review the names each quarter because account teams change. A published path also gives the client a fair way to raise a concern.","Explain what the client should include when raising an issue, such as the case number, the customer's request, and the promise already made. A complete handoff shortens the first response. Ask the client to name one backup contact for each tier so the path does not depend on a single person. That backup should be a role, not a mobile number that changes with the roster."]},{"title":"Revise after a staffing change","paragraphs":["A new supervisor, a shift change, or a vendor transition can leave a tier without an owner. Update the path before the change takes effect, not after the first missed escalation. Test one case with the new owner and confirm the clock still works. Tell the client which name changed. The client should hear about the change before the first case reaches the new owner.","Keep a version history of the path so a later review can see what was promised when. If a change removes a tier, say where those cases now go. A path that quietly loses a step is worse than an outdated one, because nobody knows the case is unprotected. Version control is part of the promise, not an administrative extra."]}],"controlTable":[{"data":"Trigger","agent":"Records the threshold and the case","manager":"Confirms the tier"},{"data":"Response clock","agent":"Acknowledges inside the window","manager":"Owns pauses and extensions"},{"data":"Handoff note","agent":"Names the next owner and backup","manager":"Accepts the case in the record"},{"data":"Missed clock","agent":"Flags the breach","manager":"Reviews the cause and the fix"}],"scripts":[{"situation":"Acknowledging a client escalation","text":"I have logged this as a tier-two escalation and named myself as the owner. You will have an update from me by three today, even if the fix is still in progress."},{"situation":"Telling a customer about a delay","text":"The correction is taking longer than I estimated, and I did not want you to wait without hearing from me. I am still the owner, and I will send another update tomorrow morning by ten."}],"faqs":[{"question":"Should the client have the account manager's mobile number?","answer":"Only if the path names when to use it and who covers when that person is away. A direct number without a backup recreates the single-person dependency the path is meant to remove."},{"question":"How many tiers should an escalation path have?","answer":"Usually two or three. Each tier must add a new authority or resource; a tier that only forwards the case adds delay without changing the outcome."}],"sources":[{"name":"Occupational Outlook Handbook: Customer Service Representatives","organization":"Bureau of Labor Statistics","date":"2026","url":"https://www.bls.gov/ooh/office-and-administrative-support/customer-service-representatives.htm","note":"Employment, wage, training, and outlook figures for customer service representatives."},{"name":"ISO 18295-1:2017 Customer contact centres","organization":"International Organization for Standardization","date":"2017","url":"https://www.iso.org/standard/64739.html","note":"Requirements for customer contact centre processes, people, and performance."},{"name":"GAO-20-283G: Assessing Data Reliability","organization":"U.S. Government Accountability Office","date":"2020","url":"https://www.gao.gov/products/gao-20-283g","note":"A practical framework for documenting data sources, testing reliability, and stating limitations."},{"name":"NIST Cybersecurity Framework 2.0","organization":"National Institute of Standards and Technology","date":"2024","url":"https://www.nist.gov/cyberframework","note":"Govern, identify, protect, detect, respond, and recover functions used for control ownership."}],"related":[{"label":"Run a new-hire nesting period without hiding the queue","href":"/blog/callcenteroutsourced-run-a-new-hire-nesting-period-without-hiding-the-queue"},{"label":"Review operations support","href":"/services/operations-support"}]},{"slug":"callcenteroutsourced-audit-an-ivr-menu-after-a-product-change","heroImage":"/daily18/callcenteroutsourced/callcenteroutsourced-audit-an-ivr-menu-after-a-product-change.webp","title":"Audit an IVR menu after a product change","excerpt":"A post-change IVR audit that checks the menu tree, the top call reasons, the recordings, and the drop-off data before the next launch.","minutes":8,"intro":"A product change can make an IVR menu wrong without touching the menu itself. A renamed plan, a retired feature, or a new billing date sends callers into an option that no longer matches their question. The queue then absorbs the confusion as extra transfers and repeat calls. An audit after every product change keeps the menu aligned with what customers actually hear and need.","published":"2026-11-18","updated":"2026-11-18","stats":[{"value":"2.67 million","label":"U.S. customer service representative jobs in 2025","note":"BLS reports about 2.7 million customer service representative jobs; the figure frames the scale of the queue workload.","source":1},{"value":"$21.53","label":"median hourly wage in May 2025","note":"BLS median pay for customer service representatives in May 2025; wages vary by industry and geography.","source":1},{"value":"289,500","label":"projected annual openings, 2025 to 2035","note":"BLS projects annual openings from replacement needs, not from queue growth.","source":1}],"sections":[{"title":"List what changed","paragraphs":["Start with the product release note and mark every name, price, date, and process that changed. Ask the client for the customer-facing version, not only the internal summary. A change that seems small to the product team can remove the words a caller uses to identify the option. Turn the list into a checklist for the audit. A checklist with a name beside each item is easier to finish before the release.","Include changes to the account portal, the mobile app, and the billing statement because callers often describe the product through those surfaces. If the app now calls a feature by a new name, the menu should use the same words. Record the old and new terms side by side for the reviewer. The reviewer should read the customer-facing page, not only the internal note."]},{"title":"Map the old path to the new one","paragraphs":["Draw the current menu tree and mark where each changed product appears. Follow the path a caller would take for the three most common questions about that product. If the path ends in a general queue, note the transfer it creates. The map shows whether the menu still routes by the customer's language. A path that requires a transfer for the most common question is a design problem.","Compare the map with the journey the client published for customers. A mismatch between the menu and the help article is a source of avoidable calls. Fix the label or the article, but do not leave both versions live. Keep the map with the audit so the next change starts from the current tree. An old screenshot in a help article can send a caller to a menu option that no longer exists."]},{"title":"Check the top call reasons","paragraphs":["Pull the top reasons for the last four weeks and mark the ones that mention the changed product. Listen to a sample of those calls and note the words customers use. A menu label built from internal terminology will miss the caller who says my bill looks different. Update the label to the customer's phrase where the meaning stays clear.","Look for reasons that should have disappeared after the change. A retired feature that still generates calls may mean the old path is still advertised somewhere. Check the website, the app store listing, and the printed insert. An IVR cannot fix a message that other channels still send. Check the app store text and the automated email footer as well."]},{"title":"Listen to the full menu","paragraphs":["Listen to every recording from the first prompt to the last option, on a real phone. Read the transcript at the same time and mark a mismatch between the spoken words and the written script. Check the option numbers, the silence, and the time a caller has to respond. A menu that sounds fine in a browser can behave differently on a mobile call.","Ask two people who did not write the script to find the option for a specific request. If they hesitate, the label is not doing its job. Note the wording they expected and compare it with the recording. Test the back and repeat keys as well, because a caller who cannot recover will press zero or hang up. Ask the tester to write down the exact key they pressed when they felt lost."]},{"title":"Test on a real phone","paragraphs":["Call the number from a mobile phone, a landline, and a headset, and record the time to reach a person for each path. A menu that works on a fast connection can time out on a slow one. Check the audio level and the background noise in each recording. Test during a busy hour as well as a quiet one.","Try the path with the phone against your ear and on speaker, because the experience differs. Ask someone with a hearing difficulty to test the menu if the client serves accessibility needs. Note any prompt that relies on a quick response without an option to repeat. The audit should produce a list a technician can act on. A technician should be able to reproduce each finding from the note alone."]},{"title":"Review the drop-off data","paragraphs":["Compare the menu drop-off before and after the change. A jump at one prompt points to a label, a recording, or a timing problem. Break the data down by channel and by hour so a peak-hour issue does not hide in the average. Read the self-service completion rate beside the drop-off. Break the data down by new and returning callers as well.","Do not assume every drop-off is a failure, because some callers find what they need and leave. Pair the data with a short sample of calls to see what happened after the exit. Record the interpretation and the sample size. A number without that context can send the team to fix the wrong prompt. The fix should name the prompt or the script that will change."]},{"title":"Update the scripts and knowledge base","paragraphs":["Change the agent scripts, the knowledge articles, and the menu labels in the same release. An agent who reads the old product name will confuse the caller who just heard the new one. Give the team a one-page summary of the change and the new path. Put the summary where agents look before a call, not only in an email.","Ask the knowledge owner to retire the old article instead of leaving both versions searchable. Add a redirect or a note that points to the new page. Check the search terms customers and agents use for the old name. Keep the old term as a synonym so a caller who uses it still finds the answer. Search the old name in the agent desktop before the release, not after."]},{"title":"Set the next review date","paragraphs":["Schedule the next IVR review before the audit closes, even if no product change is planned. A menu drifts through small edits, new promotions, and seasonal messages. Put the owner and the date in the account calendar. Review the top call reasons and the drop-off data at that meeting. Put the review on the same calendar as the product release review.","Use the audit checklist again at the next review and mark which items changed. If a fix was promised but not made, carry it forward with a new due date. A review that only listens to the first prompt is not an audit. Close the loop by telling the client what changed and what the queue should see as a result. A short written result is more useful than a recording nobody opens again."]}],"controlTable":[{"data":"Product change list","agent":"Checks each changed term","manager":"Confirms the customer-facing names"},{"data":"Menu map","agent":"Follows the top three paths","manager":"Approves label changes"},{"data":"Recording check","agent":"Listens on a real phone","manager":"Owns the re-record request"},{"data":"Drop-off review","agent":"Samples the exit calls","manager":"Sets the next review date"}],"scripts":[{"situation":"Testing the menu with a colleague","text":"Please call this number and find the option for a billing date change without telling me what you expect to hear. I want to know which words you looked for and where you hesitated."},{"situation":"Telling the client about a menu fix","text":"The new plan name is now in the first prompt and the billing option, and we retired the old recording today. The drop-off at that prompt should be measured for the next two weeks before we call the fix complete."}],"faqs":[{"question":"How often should an IVR menu be audited?","answer":"After every customer-facing product change and at least twice a year. A calendar review catches drift from small edits that no release note mentions."},{"question":"Is a lower menu drop-off always better?","answer":"No. Some callers leave because they found the answer, so pair the drop-off with the self-service completion rate and a sample of calls."}],"sources":[{"name":"Occupational Outlook Handbook: Customer Service Representatives","organization":"Bureau of Labor Statistics","date":"2026","url":"https://www.bls.gov/ooh/office-and-administrative-support/customer-service-representatives.htm","note":"Employment, wage, training, and outlook figures for customer service representatives."},{"name":"ISO 18295-1:2017 Customer contact centres","organization":"International Organization for Standardization","date":"2017","url":"https://www.iso.org/standard/64739.html","note":"Requirements for customer contact centre processes, people, and performance."},{"name":"GAO-20-283G: Assessing Data Reliability","organization":"U.S. Government Accountability Office","date":"2020","url":"https://www.gao.gov/products/gao-20-283g","note":"A practical framework for documenting data sources, testing reliability, and stating limitations."},{"name":"Privacy and Data Security Guidance","organization":"Federal Trade Commission","date":"2026","url":"https://www.ftc.gov/business-guidance/privacy-security","note":"Business guidance on protecting customer information and honoring privacy commitments."}],"related":[{"label":"Write a client escalation path that names the next owner","href":"/blog/callcenteroutsourced-write-a-client-escalation-path-that-names-the-next-owner"},{"label":"Review customer support","href":"/services/customer-support"}]},{"slug":"callcenteroutsourced-keep-a-work-from-home-readiness-check-honest-for-remote-agents","heroImage":"/daily18/callcenteroutsourced/callcenteroutsourced-keep-a-work-from-home-readiness-check-honest-for-remote-agents.webp","title":"Keep a work-from-home readiness check honest for remote agents","excerpt":"A readiness check that tests power, network, headset, and workspace before the shift and records what failed without punishing bad weather.","minutes":8,"intro":"A remote agent can pass every training module and still lose the first hour of a shift to a failed router. The queue sees an unexplained absence, while the agent sees a problem they cannot fix alone. A readiness check closes that gap only when it tests the right things and records the result in one place. The steps below keep the check useful instead of ceremonial.","published":"2026-11-18","updated":"2026-11-18","stats":[{"value":"2.67 million","label":"U.S. customer service representative jobs in 2025","note":"BLS reports about 2.7 million customer service representative jobs; the figure frames the scale of the queue workload.","source":1},{"value":"$21.53","label":"median hourly wage in May 2025","note":"BLS median pay for customer service representatives in May 2025; wages vary by industry and geography.","source":1},{"value":"289,500","label":"projected annual openings, 2025 to 2035","note":"BLS projects annual openings from replacement needs, not from queue growth.","source":1}],"sections":[{"title":"Define readiness before the shift","paragraphs":["Write the conditions an agent needs to take calls, such as power, an internet connection with enough upload speed, a working headset, and a quiet space. Keep the list short enough to check in a few minutes. Separate the conditions the agent controls from the ones the company supplies. Publish the list with the schedule so nobody discovers a requirement on the first day.","Decide what counts as ready for a voice shift versus a chat shift. A chat agent can work through a brief connection drop, while a voice agent cannot. Use the same checklist language across both so the agent is not guessing. Review the list with the client if the account has its own requirements. The client's requirements should be visible to the agent, not kept in a separate contract file."]},{"title":"Test power and network, not just the headset","paragraphs":["A headset test is easy because it produces an obvious failure, but power and network cause more lost hours. Ask the agent to confirm a backup power option and to run a speed test before the shift. Record the measured upload and download figures rather than a yes or no. A number shows a trend that a checkbox hides. A recorded number also gives the support team something to compare when the agent calls for help.","Test the connection on the same device and network the agent will use for calls. A fast phone connection does not prove the laptop is ready. Ask the agent to note whether the connection is wired or wireless and whether anyone else is using it. A household that streams video during the shift can turn a passing test into a failing call."]},{"title":"Record the result in one place","paragraphs":["Put the check in the same system the supervisor uses for attendance, not in a separate spreadsheet. The record should show the time, the result, the device, and the action taken. A supervisor who sees a failed check should know who is handling it without asking the agent again. Keep the record for the period the client and the law require.","Do not ask the agent to send a screenshot to a chat channel that disappears. A screenshot can support a diagnosis, but the case record should hold the outcome. If the check is manual, name the person who enters the result. An unrecorded check cannot support a staffing decision or a later review. The supervisor should be able to see the result before the shift starts."]},{"title":"Handle a failed check","paragraphs":["Give the agent a short path for a failed check: try the backup connection, contact the support line, and tell the supervisor before the shift starts. The supervisor should decide whether to move the agent to chat, adjust the start time, or mark the time off. Write the decision rules so the outcome does not depend on who is on duty. Write the rules in the same guide the supervisor uses for attendance.","Do not require the agent to use paid leave for a company-side outage. Separate the failures the company owns from the failures the agent owns, and record the category. A power cut in the agent's area is not the same as a broken company laptop. The category should drive the fix and the pay decision. The pay decision should follow the category, not the supervisor's impression."]},{"title":"Avoid a check that punishes weather","paragraphs":["A storm can take out power and internet for days, and a check that treats every outage as an attendance problem will punish the agent for the weather. Build a temporary exception with a review date and a way to confirm the event. Ask for the minimum evidence needed, such as a utility notice or a provider message. The exception should be easy to request during the event, not after it.","Do not publish a blanket rule that every outage needs a receipt within an hour, because the agent may be managing the same emergency at home. Give the supervisor authority to approve a short exception and document it later. Review the exceptions by region to see whether the check needs a local backup plan. A regional pattern may justify a company-provided backup connection."]},{"title":"Review readiness after a site outage","paragraphs":["When a site or system outage affects many agents, review the readiness data before blaming individual connections. A VPN failure can look like a home network problem from the agent's side. Compare the failures by provider, region, and time. The pattern often points to a company-side fix rather than an individual connection. Compare the failures with the provider's status page for the same hours.","Share the finding with the client if the outage affected service levels. State what was known, when it was known, and what changed. Do not publish an agent's name or address in the summary. The review should improve the backup plan, not create a list of people to watch. The summary should name the fix and the date it will be tested."]},{"title":"Report readiness to the client","paragraphs":["Give the client a monthly summary of checks passed, checks failed, and the reasons. Separate the company-side causes from the agent-side causes and show the time lost. A client who sees the categories can judge whether the support model is working. Include the fix that is in progress and its owner. Show the time lost in hours so the client can compare it with the service impact.","Do not report a single readiness percentage without the sample and the period. A small team can swing several points on one outage. Show the trend across three months and note any change to the check itself. A measure that changes definition without a note is not comparable. Keep the definition stable for at least a quarter before changing it."]},{"title":"Refresh the check each quarter","paragraphs":["Review the checklist with the agents who use it, because they know which step is stale. A new headset model or a changed VPN client can make the old instructions wrong. Update the screenshots and the support number at the same time. Tell the team what changed so they do not keep using the old steps. A short checklist that agents finish is better than a thorough one they skip.","Set a date for the next review and name the owner. Keep the previous version so a later question can be answered. If the check grows beyond a few minutes, cut a step rather than letting compliance erode. A check that agents skip is worse than a shorter check they complete every shift. The owner should be a role that survives a staffing change."]}],"controlTable":[{"data":"Power backup","agent":"Confirms the option before the shift","manager":"Approves a short exception"},{"data":"Network test","agent":"Records the measured speed","manager":"Reviews failures by provider"},{"data":"Headset and device","agent":"Tests on the call device","manager":"Owns replacement and support"},{"data":"Failed check","agent":"Follows the backup path","manager":"Decides the shift outcome"}],"scripts":[{"situation":"Reporting a failed connection","text":"My connection dropped twice during the speed test, and I have already switched to the backup hotspot. I am telling you before the shift so we can decide whether I start on chat or wait for the provider."},{"situation":"Explaining a weather exception","text":"The utility notice says power will return this afternoon, and I have a phone hotspot for the chat queue. I am asking for a short exception today and will send the notice when the connection is stable."}],"faqs":[{"question":"Should an agent pay for a backup internet connection?","answer":"That depends on the employment agreement and local law. Decide the policy in writing before a failure, and do not surprise the agent with a cost during an outage."},{"question":"Is a speed test enough to prove readiness?","answer":"No. Test on the actual call device and during a busy hour, and record the result in the same system the supervisor uses for attendance."}],"sources":[{"name":"Occupational Outlook Handbook: Customer Service Representatives","organization":"Bureau of Labor Statistics","date":"2026","url":"https://www.bls.gov/ooh/office-and-administrative-support/customer-service-representatives.htm","note":"Employment, wage, training, and outlook figures for customer service representatives."},{"name":"Fact Sheet #64: Call Centers under the Fair Labor Standards Act","organization":"U.S. Department of Labor, Wage and Hour Division","date":"2008","url":"https://www.dol.gov/agencies/whd/fact-sheets/64-flsa-call-centers","note":"Hours-worked, rest-period, and recordkeeping rules for call center employees."},{"name":"Fair Labor Standards Act","organization":"U.S. Department of Labor, Wage and Hour Division","date":"2026","url":"https://www.dol.gov/agencies/whd/flsa","note":"Federal minimum wage, overtime, hours-worked, and recordkeeping obligations."},{"name":"Privacy and Data Security Guidance","organization":"Federal Trade Commission","date":"2026","url":"https://www.ftc.gov/business-guidance/privacy-security","note":"Business guidance on protecting customer information and honoring privacy commitments."}],"related":[{"label":"Audit an IVR menu after a product change","href":"/blog/callcenteroutsourced-audit-an-ivr-menu-after-a-product-change"},{"label":"Review operations support","href":"/services/operations-support"}]}] as unknown as readonly BlogPost[];
